else:
    try:
        item=json.loads(sys.argv[1]); expectedMoid=sys.argv[2]; expectedName=sys.argv[3]; orgMoid=sys.argv[4]; action=sys.argv[5]; preModTime=sys.argv[6]; preStatus=sys.argv[7]; mode=sys.argv[8]
        if item.get("Moid")!=expectedMoid or item.get("Name")!=expectedName or item.get("ClassId")!="workload.WorkloadDeployment" or item.get("ObjectType")!="workload.WorkloadDeployment": raise ValueError("Polled deployment identity does not match.")
        org=item.get("Organization")
        if not isinstance(org,dict) or org.get("Moid")!=orgMoid or org.get("ObjectType")!="organization.Organization": raise ValueError("Polled Organization relationship does not match.")
        modTime=str(item.get("ModTime","")).strip(); datetime.datetime.fromisoformat(modTime.replace("Z","+00:00"))
        observedStatus=str(item.get("Status","")).strip(); lastAction=str(item.get("LastAction","None")).strip()
        allowedStatuses={"Draft","ReadyToDeploy","InProgress","Ok","Failed","ChangesScheduled","Suspended"}; allowedActions={"None","PrepareToDeploy","Deploy","Suspend","Retry","Resume","Undeploy","ReEvaluateQualifiers"}
        if observedStatus not in allowedStatuses or lastAction not in allowedActions: raise ValueError("Polled status or LastAction is outside the documented enum.")
        ack=(lastAction==action and modTime!=preModTime) or observedStatus!=preStatus; acknowledged="true" if ack else "false"
        successByMode={"prepare":{"ReadyToDeploy"},"deploy":{"Ok"},"undeploy":{"Draft"}}
