        else: successStates=successByMode.get(mode,set())
        if ack and observedStatus=="Failed": pollState="failure"
        elif ack and mode=="deploy" and observedStatus=="ChangesScheduled": pollState="scheduled"
        elif ack and observedStatus in successStates: pollState="success"
        else: pollState="progress"
