        status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
    except Exception as exc:
        failureError="The lifecycle poll response failed validation: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"requestAccepted":True,"preMutationModTime":preModTime,"raceDisclosure":"The lookup and PATCH were separate and may have raced a concurrent same-item change."},separators=(",",":"))
